// What's new (REL-4, specs/release-v2.md): the release notes the app ships with.
//
// release-notes/releases.json is generated by the release pipeline (REL-1) and
// bundled here at build time, so desktop has every note offline. Newest first:
// { releases: [{ version, date, highlights, items: [{ type, text }] }] }.
// Pure data and rules; no React.

import { z } from "zod";

import releasesJson from "../../../../../release-notes/releases.json";
import { compareVersions } from "../../lib/versions";

export { compareVersions, newerVersion } from "../../lib/versions";

export const NOTE_TYPES = ["new", "improved", "fixed", "security"] as const;
export type NoteType = (typeof NOTE_TYPES)[number];

export type ReleaseItem = { type: NoteType; text: string };
export type Release = {
  version: string;
  /** YYYY-MM-DD */
  date: string;
  highlights: string[];
  items: ReleaseItem[];
};

/** A security note always reads as this one line (the release pipeline's rule). */
export const SECURITY_LINE = "Security and reliability improvements.";

const itemSchema = z.object({ type: z.enum(NOTE_TYPES), text: z.string().trim().min(1) });
const releaseSchema = z.object({
  version: z.string().trim().min(1),
  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
  highlights: z.array(z.string().trim().min(1)).catch([]),
  // A bad item drops alone; the rest of the release still shows.
  items: z
    .array(z.unknown())
    .catch([])
    .transform((raw) =>
      raw.flatMap((item) => {
        const parsed = itemSchema.safeParse(item);
        return parsed.success ? [parsed.data] : [];
      }),
    ),
});

/** Reads a releases.json payload; a bad release drops alone, newest first. */
export function parseReleases(raw: unknown): Release[] {
  const list = (raw as { releases?: unknown } | null)?.releases;
  if (!Array.isArray(list)) return [];
  const releases = list.flatMap((entry) => {
    const parsed = releaseSchema.safeParse(entry);
    return parsed.success ? [parsed.data] : [];
  });
  return releases.sort((a, b) => compareVersions(b.version, a.version));
}

/** Every release the app was built with, newest first. */
export const RELEASES: Release[] = parseReleases(releasesJson);

export function findRelease(version: string, releases: Release[] = RELEASES): Release | null {
  return releases.find((r) => r.version === version) ?? null;
}

export type ReleaseGroup = { key: "new" | "improved" | "fixed"; label: string; items: string[] };

const GROUP_LABELS = { new: "New", improved: "Improved", fixed: "Fixed" } as const;

/** New, Improved, Fixed, in that order, empty groups left out. Security notes
 *  join Fixed as the one fixed line, once. */
export function groupItems(release: Release): ReleaseGroup[] {
  const by: Record<ReleaseGroup["key"], string[]> = { new: [], improved: [], fixed: [] };
  let security = false;
  for (const item of release.items) {
    if (item.type === "security") security = true;
    else by[item.type].push(item.text);
  }
  if (security) by.fixed.push(SECURITY_LINE);
  return (Object.keys(GROUP_LABELS) as ReleaseGroup["key"][])
    .filter((key) => by[key].length > 0)
    .map((key) => ({ key, label: GROUP_LABELS[key], items: by[key] }));
}

/** "18 October 2026" from "2026-10-18" (read as a calendar date, not a moment). */
export function formatReleaseDate(date: string): string {
  const [y, m, d] = date.split("-").map(Number);
  if (!y || !m || !d) return date;
  return new Date(Date.UTC(y, m - 1, d)).toLocaleDateString("en-GB", {
    day: "numeric",
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  });
}

// ── When the "Updated to X" toast shows ───────────────────────────────────────

export type WhatsNewDecision =
  /** The person's synced preferences haven't been read yet this session. */
  | "wait"
  /** Show the toast once, and record the version as seen. */
  | "show"
  /** Record the version as seen without a toast. */
  | "mark"
  /** Nothing to do. */
  | "none";

/**
 * After the running version changes from the last one this person saw, the
 * toast shows once, if the version has notes. A person who never had a
 * version recorded (from before What's new, or someone new) sees it only if
 * they were already using Moduo before the release (`knownSince`, the earliest
 * stamp their preferences carry). Versions only move forward, so an older
 * build (a rollback, another device behind) never records itself.
 */
export function whatsNewDecision(input: {
  running: string;
  lastSeen: string | null;
  prefsReady: boolean;
  release: Release | null;
  knownSince: string | null;
}): WhatsNewDecision {
  const { running, lastSeen, prefsReady, release, knownSince } = input;
  if (!prefsReady) return "wait";
  if (lastSeen && compareVersions(running, lastSeen) <= 0) return "none";
  if (!release) return "mark";
  if (!lastSeen) {
    const since = knownSince ? Date.parse(knownSince) : Number.NaN;
    if (!Number.isFinite(since) || since >= Date.parse(`${release.date}T00:00:00Z`)) return "mark";
  }
  return "show";
}
